const IS_ADMIN=false;const ADMIN_URL='https://estreladaconciencia-admin.carloshsgandracode.chatgpt.site';

'use strict';
/* API-backed interface: the server owns authorization, pricing, availability and persistence. */
const ZONE='America/Sao_Paulo';
const $=(q,el=document)=>el.querySelector(q), $$=(q,el=document)=>[...el.querySelectorAll(q)];
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const uid=()=>crypto.randomUUID?crypto.randomUUID():Date.now().toString(36)+Math.random().toString(36).slice(2);
const money=n=>new Intl.NumberFormat('pt-BR',{style:'currency',currency:'BRL'}).format(n);
const dateObj=d=>new Date(d+'T12:00:00-03:00');
const fmtDate=d=>dateObj(d).toLocaleDateString('pt-BR',{day:'2-digit',month:'long',year:'numeric',timeZone:ZONE});
const dateKey=d=>{const p=new Intl.DateTimeFormat('en-CA',{timeZone:ZONE,year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(d);return ['year','month','day'].map(k=>p.find(x=>x.type===k).value).join('-')};
const today=()=>dateKey(new Date());
const addDays=(d,n)=>{let x=dateObj(d);x.setUTCDate(x.getUTCDate()+n);return dateKey(x)};
const minutes=t=>Number(t.slice(0,2))*60+Number(t.slice(3));
const timeString=m=>String(Math.floor(m/60)).padStart(2,'0')+':'+String(m%60).padStart(2,'0');
const instant=(d,t)=>new Date(d+'T'+t+':00-03:00').getTime();
const validDate=d=>/^\d{4}-\d{2}-\d{2}$/.test(d)&&Number.isFinite(dateObj(d).getTime())&&dateKey(dateObj(d))===d;
const validTime=t=>/^([01]\d|2[0-3]):[0-5]\d$/.test(t);
const defaults=()=>({version:1,rev:0,services:[{id:'avulsa',title:'Jogo de Tarô',duration:60,price:97,description:'Leitura individual para acolher sua questão, observar caminhos e organizar possibilidades com clareza.',art:0,active:true},{id:'mentoria',title:'Reiki',duration:60,price:97,description:'Sessão de cuidado energético conduzida com presença, acolhimento e respeito ao seu momento.',art:1,active:true},{id:'mapa',title:'Ritual de Ayahuasca',duration:240,price:0,description:'Uma experiência ritualística que exige conversa prévia, orientações e avaliação individual pelo WhatsApp.',art:2,active:false},{id:'retorno',title:'Retorno de consulta',duration:30,price:97,description:'Retorno reservado para acompanhamentos já iniciados.',art:3,active:false}],settings:{name:'',bio:'Aqui, o tarot não entrega uma sentença. As cartas abrem uma conversa sobre o que você está vivendo — e sobre os caminhos que ainda pode escolher.\n\nPrefiro boas perguntas a respostas prontas. Cada leitura tem tempo para escuta, contexto e reflexão, sem promessas de um futuro fechado.',whatsapp:'11945915395',address:'',video:'',online:true,presential:false,lead:24,interval:30,blocked:[],week:[{on:false,start:'09:00',end:'18:00'},{on:true,start:'09:00',end:'18:00'},{on:true,start:'09:00',end:'18:00'},{on:true,start:'09:00',end:'18:00'},{on:true,start:'09:00',end:'18:00'},{on:true,start:'09:00',end:'18:00'},{on:true,start:'09:00',end:'13:00'}],configured:true,catalogVersion:2},appointments:[]});
let memory=defaults(),toastTimer,clientEmail='',adminTab='agenda',adminFilter='todos',searchTerm='';
let booking={step:0,service:'avulsa',date:'',time:'',mode:'online',view:'cards',offset:0,customer:{name:'',email:'',phone:'',topic:'',intention:''},consent:false};
function read(){return memory}
async function fetchState(){const res=await fetch('/api/state',{cache:'no-store',credentials:'same-origin'});const data=await res.json();if(!res.ok)throw Error(data.error||'Não foi possível carregar a agenda.');memory=data;return data}
async function transact(fn){
 const current=structuredClone(memory),next=structuredClone(current),result=fn(next);let body;
 const added=next.appointments.filter(x=>!current.appointments.some(y=>y.id===x.id));
 const changed=next.appointments.filter(x=>{const old=current.appointments.find(y=>y.id===x.id);return old&&JSON.stringify(old)!==JSON.stringify(x)});
 if(added.length===1)body={type:'create',appointment:added[0],consent:booking.consent};
 else if(changed.length===1)body={type:'update',appointment:changed[0],version:current.appointments.find(x=>x.id===changed[0].id)._version};
 else if(IS_ADMIN&&(JSON.stringify(next.settings)!==JSON.stringify(current.settings)||JSON.stringify(next.services)!==JSON.stringify(current.services)))body={type:'config',settings:next.settings,services:next.services,version:current.rev};
 else throw Error('Nenhuma alteração válida para salvar.');
 const res=await fetch('/api/action',{method:'POST',headers:{'Content-Type':'application/json'},credentials:'same-origin',body:JSON.stringify(body)});
 const data=await res.json();if(!res.ok){if(res.status===409)await fetchState();throw Error(data.error||'Não foi possível salvar. Tente novamente.')}memory=data;return result;
}

const activeStatus=s=>['pendente','confirmado'].includes(s);
function available(store,serviceId,date,exclude=''){
 const service=store.services.find(s=>s.id===serviceId&&s.active);if(!service||!validDate(date)||date<today()||date>addDays(today(),180)||store.settings.blocked.includes(date))return [];
 const day=store.settings.week[dateObj(date).getUTCDay()];if(!day.on)return [];const list=[];
 for(let m=minutes(day.start);m+service.duration<=minutes(day.end);m+=store.settings.interval){const t=timeString(m);if(instant(date,t)<=Date.now()+3600000)continue;const ownExcluded=store.appointments.find(a=>a.id===exclude);const conflict=[...store.appointments,...(store.busy||[]).filter(b=>!ownExcluded||b.date!==ownExcluded.date||b.time!==ownExcluded.time)].some(a=>a.id!==exclude&&a.date===date&&activeStatus(a.status)&&m<minutes(a.time)+a.duration&&m+service.duration>minutes(a.time));if(!conflict)list.push(t)}return list;
}
function canChange(a,s=read()){return activeStatus(a.status)&&instant(a.date,a.time)-Date.now()>=s.settings.lead*3600000}
function svgArt(n=0){const start='<svg viewBox="0 0 180 240" fill="none" stroke="currentColor" stroke-width="1.1" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">';const end='</svg>';let v='';
 if(n===0){v='<path d="M35 197V89a55 55 0 0 1 110 0v108M25 202h130M35 214h110"/><circle cx="90" cy="106" r="29"/><circle cx="90" cy="106" r="23"/><path d="M83 102c-3-3-6-3-9 0m32 0c-3-3-6-3-9 0m-7 1-3 11h6m-9 6q6 4 12 0M90 65V49m0 98v16M49 106H33m98 0h16M61 77 49 65m70 70 12 12M61 135l-12 12m70-70 12-12M20 224q30-47 70-19 40-28 70 19M48 176q18-20 42 3 24-23 42-3"/><path d="M60 176q-6-22-19-22 0 20 19 22m60 0q6-22 19-22 0 20-19 22M90 29v-9m-5 5h10"/>'}
 else if(n===1){v='<path d="M50 220V80a40 40 0 0 1 80 0v140M40 220h100M90 203V128M90 176q-35 0-33-30 28 0 33 30m0-16q35 0 33-30-28 0-33 30m0 40q-39 0-38-23 30-2 38 23m0-19q38 0 37-23-29-2-37 23"/><path d="M105 65a29 29 0 1 0 15 47 27 27 0 0 1-15-47Z"/><circle cx="27" cy="112" r="3"/><circle cx="152" cy="158" r="3"/><path d="M26 172h12m-6-6v12M139 61h12m-6-6v12M72 21h8m-4-4v8"/>'}
 else if(n===2){v='<circle cx="90" cy="117" r="65"/><circle cx="90" cy="117" r="53"/><circle cx="90" cy="117" r="21"/><path d="m90 42 8 53 19-29-15 39 47-20-38 32 44 16-47 0 20 35-31-28-7 52-8-52-29 30 18-38-43 1 40-16-40-30 44 18-15-40 24 31Z"/><path d="M90 17v14m-7-7h14M90 203v19M21 202h138M38 215h104"/><circle cx="90" cy="117" r="6"/>'}
 else{v='<path d="M27 195V89a63 63 0 0 1 126 0v106M20 208h140M33 219h114M53 186l21-47m53 47-21-47M69 138q21-14 42 0l-4-37H73Z"/><path d="M85 138v31m10-31v31M74 173h32M90 86V57m-12 19 12 10 12-10M46 115a47 47 0 0 1 39-59m50 65a47 47 0 0 1-37 39M44 105l2 10 10-3m78 20 1-11-11 2"/><circle cx="90" cy="37" r="3"/>'}return start+v+end;
}
function toast(text){$('#toast').textContent=text;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').textContent='',5500)}
function download(name,data,type){const url=URL.createObjectURL(new Blob([data],{type}));const a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),30000)}
function modal(title,html){const d=$('#dialog');d.innerHTML='<div class="dialog-top"><h2 id="dialog-title">'+esc(title)+'</h2><button class="close" aria-label="Fechar janela">×</button></div>'+html;$('.close',d).onclick=()=>d.close();if(!d.open)d.showModal();return d}
function contact(){const s=read().settings;if(s.whatsapp){const digits=s.whatsapp.replace(/\D/g,'');window.open('https://wa.me/55'+digits+'?text='+encodeURIComponent('Olá! Vim pelo site do Instituto Estrela da Consciência e gostaria de saber mais sobre os atendimentos.'),'_blank','noopener,noreferrer')}else modal('Vamos conversar','<p>O número de WhatsApp ainda não foi informado. Por enquanto, entre em contato pelo perfil de referência.</p><a class="btn" href="https://www.instagram.com/estreladaconciencia/" target="_blank" rel="noopener noreferrer">Abrir Instagram ↗</a><p style="margin-top:20px">Na área da taróloga, o campo Contato ativa o botão de WhatsApp com uma mensagem pronta.</p>')}
function privacy(){modal('Seus dados, com cuidado','<p>Agendamentos, contato, intenções e anotações são armazenados no banco de dados do ateliê. O acesso ao seu caderno exige autenticação e cada conta acessa apenas seus próprios encontros.</p><p>A administração é restrita à conta autorizada da profissional. As anotações da leitura ficam visíveis a você e à administração.</p><p>Você pode solicitar correção ou exclusão dos seus dados pelo contato do ateliê. Evite inserir dados médicos, documentos ou outras informações sensíveis na intenção.</p><p>Não há cobrança nem envio automático de mensagens. O WhatsApp e Instagram são serviços externos. Somente a preferência de tema fica salva neste navegador.</p>')}

function home(){const s=read();return `<section class="wrap hero"><div class="hero-copy"><div class="eyebrow">Tarot, escuta & possibilidades</div><h1>Nem tudo pede<br>uma resposta.<em>Às vezes,<br>uma boa pergunta.</em></h1><p>As cartas entram na conversa. Você traz o que está vivendo. Juntas, olhamos para o que merece atenção — sem decidir por você.</p><div class="hero-actions"><a class="btn" href="#book">Escolher minha leitura <span aria-hidden="true">↗</span></a><a class="text-link" href="#how">Como acontece <span aria-hidden="true">↓</span></a></div><div class="hero-foot"><span></span> Atendimento individual <span></span> No seu tempo, com presença</div></div><div class="hero-art" role="img" aria-label="Duas cartas autorais de tarot: A Lua em azulado e O Sol em roxo, ilustradas com traços dourados"><div class="art-orbit"></div><span class="art-number">ARQUIVO DO ATELIÊ / 01</span><div class="hero-card back"><div class="inner"><span class="roman">XVIII</span>${svgArt(1)}<span class="card-name">A LUA</span></div></div><div class="hero-card front"><div class="inner"><span class="roman">XIX</span>${svgArt(0)}<span class="card-name">O SOL</span></div></div><span class="vertical-note">ENTRE O QUE VOCÊ SENTE E O QUE ESCOLHE.</span><span class="art-note">a próxima carta é uma conversa.</span></div></section><div class="wrap"><div class="ribbon"><span>Escuta sem pressa</span><i aria-hidden="true">✧</i><span>Sem verdades prontas</span><i aria-hidden="true">✧</i><span>Escolhas que são suas</span></div></div><section id="services" class="wrap section"><div class="section-heading"><div><div class="eyebrow">01 / Escolha como chegar</div><h2>Uma leitura para<br><em>cada momento.</em></h2></div><p>Nem toda pergunta precisa do mesmo espaço. Conheça as formas de sentar à mesa.${!s.settings.configured?'<br><small>Valores demonstrativos, editáveis no painel.</small>':''}</p></div><div class="services">${s.services.filter(x=>x.active).map((x,i)=>`<article class="service"><div class="service-art"><span class="number">0${i+1}</span>${svgArt(x.art)}</div><h3>${esc(x.title)}</h3><p>${esc(x.description)}</p><div class="service-meta"><span>${x.duration} minutos${x.id==='mentoria'?' / encontro':''}</span><strong>${money(x.price)}${x.id==='mentoria'?' / mês':''}</strong></div><a class="text-link" href="#book/${x.id}">Escolher esta leitura <span aria-hidden="true">↗</span></a></article>`).join('')}</div>${!s.services.some(x=>x.active)?'<p>As leituras estão sendo reorganizadas. Fale comigo pelo contato abaixo.</p>':''}</section><section class="about" id="about"><div class="wrap about-grid"><div class="about-illustration" aria-hidden="true">${svgArt(1)}</div><div><div class="eyebrow">02 / O jeito do ateliê</div><h2>Eu abro as cartas.<br><em>Você abre a conversa.</em></h2>${s.settings.bio.split('\n').filter(Boolean).map(p=>'<p>'+esc(p)+'</p>').join('')}<div class="signature">${esc(s.settings.name||'estreladaconciencia')}</div><a class="text-link" style="margin-top:20px" href="https://www.instagram.com/estreladaconciencia/" target="_blank" rel="noopener noreferrer">Mais do ateliê no Instagram ↗</a></div></div></section><section class="wrap section steps-layout" id="how"><div><div class="eyebrow">03 / Antes de sentar à mesa</div><h2>Da pergunta<br><em>ao encontro.</em></h2><p style="font-size:13px;max-width:290px">Você não precisa saber nada sobre tarot. Nem chegar com tudo organizado.</p><a class="text-link" href="#book">Encontrar meu horário ↗</a></div><div><div class="step-row"><span>01</span><div><h3>Escolha seu espaço.</h3><p>Uma leitura pontual ou um acompanhamento. Cada formato tem uma proposta, um tempo e um valor definidos.</p></div></div><div class="step-row"><span>02</span><div><h3>Vire uma carta, reserve um tempo.</h3><p>As cartas da agenda revelam dias disponíveis. Escolha o horário e conte o que gostaria de trazer para a conversa.</p></div></div><div class="step-row"><span>03</span><div><h3>O encontro continua no caderno.</h3><p>Depois da consulta, volte às cartas e às anotações compartilhadas pela taróloga no seu diário de acompanhamento.</p></div></div></div></section><section class="wrap section rule faq-layout" id="faq"><div><div class="eyebrow">04 / Algumas respostas, antes</div><h2>Sem mistério<br><em>para começar.</em></h2><p style="font-size:13px;max-width:260px">Ficou alguma pergunta sobre o atendimento?</p><button class="text-link" data-contact>Falar comigo ↗</button></div><div class="faq-list"><details><summary>O tarot prevê exatamente o que vai acontecer?</summary><p>A proposta do ateliê é usar as cartas como linguagem simbólica para refletir sobre questões e possibilidades. Não há garantia de acontecimentos ou resultados.</p></details><details><summary>Como funciona a consulta online?</summary><p>Você escolhe a modalidade online ao reservar. Após a confirmação, o link informado pela taróloga aparece no resumo da consulta e no seu caderno. Procure um lugar tranquilo e teste sua conexão.</p></details><details><summary>Posso remarcar ou cancelar?</summary><p>Sim, pelo Meu caderno, com pelo menos ${s.settings.lead} horas de antecedência. Depois desse prazo, fale diretamente com a taróloga. Não há cobrança ou reembolso automático neste site.</p></details><details><summary>Como funciona a mentoria mensal?</summary><p>A proposta inicial é de quatro encontros de ${s.services.find(x=>x.id==='mentoria').duration} minutos. O agendamento reserva o primeiro; os demais são combinados com a taróloga e registrados pelo painel. Não há assinatura ou renovação automática.</p></details><details><summary>Preciso pagar ao reservar?</summary><p>Não. A reserva fica pendente até a confirmação da taróloga. Valores e forma de pagamento são combinados no contato; o site não cobra nem coleta dados de cartão.</p></details><details><summary>Posso levar qualquer tipo de pergunta?</summary><p>Você pode trazer relações, trabalho, decisões ou uma questão aberta. A leitura não substitui atendimento médico, psicológico, jurídico ou financeiro.</p></details></div></section><section class="closing"><div><div class="eyebrow" style="margin-bottom:14px">A mesa está posta.</div><h2>Qual pergunta veio com você?</h2><p>Não precisa estar pronta. Podemos começar por aí.</p></div><a class="btn light" href="#book">Reservar meu encontro <span aria-hidden="true">↗</span></a></section>`}
function pageTop(k,title,description){return `<section class="wrap page-top"><a class="back-link" href="#home">← Voltar ao ateliê</a><div class="eyebrow">${k}</div><h1>${title}</h1><p>${description}</p></section>`}
function selectedService(){return read().services.find(x=>x.id===booking.service)||read().services[0]}
function bookingAside(){const s=selectedService();return `<aside class="booking-side">${svgArt(s.art)}<div class="eyebrow">Seu lugar à mesa</div><h3>${esc(s.title)}</h3><p>${esc(s.description)}</p><div class="meta">${s.duration} minutos · ${money(s.price)}</div><p style="margin-top:18px">${booking.date?fmtDate(booking.date):'O dia ainda está por vir.'}<br>${booking.time?booking.time+' · São Paulo':''}</p><p class="muted">Você envia uma solicitação. A taróloga confirma os detalhes antes do encontro.</p></aside>`}
function bookPage(){return pageTop('Seu encontro / um passo de cada vez','Reserve um tempo<br><em>para a sua pergunta.</em>','Escolha sua leitura e encontre um horário. Todas as datas seguem o fuso de São Paulo.')+`<section class="wrap workspace"><div class="flow"><div class="panel" id="booking-panel">${bookingPanel()}</div>${bookingAside()}</div></section>`}
function bookingPanel(){const s=read(),sv=selectedService();if(booking.step>=2&&!s.user&&!IS_ADMIN)return '<h2>Seu caderno começa com você.</h2><p>Entre na sua conta para proteger seus agendamentos e acessá-los de qualquer aparelho.</p><a class="btn" href="/signin-with-chatgpt?return_to=%2F%23book" target="_top">Entrar com ChatGPT →</a>';if(booking.done){const a=s.appointments.find(x=>x.id===booking.done);return a?confirmation(a):'<p>Reserva não encontrada.</p>'}let html='<ol class="progress" aria-label="Etapas do agendamento">'+['Leitura','Dia e hora','Sobre você','Revisão'].map((x,i)=>`<li class="${booking.step>=i?'active':''}" ${booking.step===i?'aria-current="step"':''}>0${i+1} · ${x}</li>`).join('')+'</ol>';
 if(booking.step===0)html+=`<h2>O que pede atenção?</h2><p class="muted">Escolha a forma da nossa conversa.</p><div class="choice-services">${s.services.filter(x=>x.active).map(x=>`<button class="choice" data-service="${x.id}" aria-pressed="${booking.service===x.id}">${svgArt(x.art)}<span class="eyebrow">${x.duration} minutos</span><h3>${esc(x.title)}</h3><p>${money(x.price)}${x.id==='mentoria'?' / mês':''}</p></button>`).join('')}</div><p class="muted" style="margin-top:20px">${esc(sv.description)}${!s.settings.configured?' Valores demonstrativos.':''}</p><div class="flow-actions"><span class="muted">01 de 04</span><button class="btn" id="next" ${!s.services.some(x=>x.id===booking.service&&x.active)?'disabled':''}>Escolher dia e hora →</button></div>`;
 if(booking.step===1)html+=`<h2>Abra espaço na sua agenda.</h2><p class="muted">Escolha uma carta para revelar os horários daquele dia.</p><label for="booking-mode">Como prefere o encontro?</label><select id="booking-mode">${s.settings.online?'<option value="online" '+(booking.mode==='online'?'selected':'')+'>Online · por videochamada</option>':''}${s.settings.presential?'<option value="presencial" '+(booking.mode==='presencial'?'selected':'')+'>Presencial · '+esc(s.settings.address)+'</option>':''}</select>${!s.settings.online&&!s.settings.presential?'<div class="notice">Nenhuma modalidade disponível. Fale com o ateliê para combinar seu encontro.</div>':''}<div class="mode-switch" role="group" aria-label="Visualização de datas"><button class="btn outline small" id="view-cards" aria-pressed="${booking.view==='cards'}">Escolher por cartas</button><button class="btn outline small" id="view-list" aria-pressed="${booking.view==='list'}">Ver em lista</button></div>${datePicker()}<div class="flow-actions"><button class="text-link" id="prev">← Voltar</button><button class="btn" id="next" ${!booking.date||!booking.time?'disabled':''}>Continuar →</button></div>`;
 if(booking.step===2){const c=booking.customer;html+=`<h2>Quem vem para a conversa?</h2><p class="muted">Seus dados serão usados para organizar a consulta. Evite informações sensíveis na intenção.</p><form id="client-form" novalidate><div class="field"><label for="name">Como você gosta de ser chamada(o)? *</label><input id="name" name="name" autocomplete="name" required minlength="2" maxlength="100" value="${esc(c.name)}"></div><div class="field-grid"><div class="field"><label for="email">E-mail *</label><input type="email" id="email" name="email" ${!IS_ADMIN?'readonly':''} autocomplete="email" required maxlength="180" value="${esc(c.email)}"></div><div class="field"><label for="phone">Celular com DDD *</label><input type="tel" id="phone" name="phone" autocomplete="tel-national" inputmode="tel" maxlength="16" placeholder="(11) 99999-9999" value="${esc(c.phone)}"></div></div><div class="field"><label for="topic">O que você gostaria de olhar? *</label><select id="topic" name="topic" required><option value="">Escolha um tema</option>${['Relações e afetos','Trabalho e projetos','Uma decisão','Meu momento atual','Quero deixar em aberto'].map(v=>`<option ${c.topic===v?'selected':''}>${v}</option>`).join('')}</select></div><div class="field"><label for="intention">Se quiser, me conte um pouco mais.</label><textarea id="intention" name="intention" maxlength="1500" aria-describedby="intention-help">${esc(c.intention)}</textarea><small id="intention-help">Até 1.500 caracteres. Não inclua informações sensíveis.</small></div><label class="check"><input type="checkbox" name="consent" ${booking.consent?'checked':''} required><span>Concordo com o uso dos meus dados para o atendimento e com a regra de ${s.settings.lead}h para remarcação e cancelamento. *</span></label><div id="form-error" role="alert"></div><div class="flow-actions"><button type="button" class="text-link" id="prev">← Voltar</button><button class="btn" type="submit">Revisar meu encontro →</button></div></form>`}
 if(booking.step===3)html+=`<h2>Um último olhar.</h2><p class="muted">Confira os detalhes antes de reservar.</p>${summary({...booking.customer,title:sv.title,duration:sv.duration,price:sv.price,date:booking.date,time:booking.time,mode:booking.mode})}<p style="font-size:12px"><strong>Sua intenção:</strong> ${esc(booking.customer.topic)}<br>${esc(booking.customer.intention||'Você prefere contar no encontro.')}</p><div class="notice">A solicitação fica pendente até a confirmação da taróloga. Nenhum pagamento será realizado.${sv.id==='mentoria'?' Você está reservando o primeiro encontro da mentoria. Os demais serão combinados no atendimento.':''}</div><div id="form-error" role="alert"></div><div class="flow-actions"><button class="text-link" id="prev">← Ajustar dados</button><button class="btn" id="reserve">Enviar minha reserva ↗</button></div>`;return html;
}
function datePicker(){const s=read(),start=addDays(today(),booking.offset);const ds=Array.from({length:14},(_,i)=>addDays(start,i)).filter(d=>available(s,booking.service,d).length);return `<div class="month-bar"><button id="earlier" aria-label="Duas semanas anteriores" ${booking.offset===0?'disabled':''}>←</button><strong>${dateObj(start).toLocaleDateString('pt-BR',{day:'numeric',month:'short',timeZone:ZONE})} — ${dateObj(addDays(start,13)).toLocaleDateString('pt-BR',{day:'numeric',month:'short',timeZone:ZONE})}</strong><button id="later" aria-label="Próximas duas semanas" ${booking.offset>=168?'disabled':''}>→</button></div>${ds.length?`<div class="${booking.view==='cards'?'date-cards':'date-list'}" role="group" aria-label="Dias disponíveis">${ds.map(d=>`<button class="date-card" data-date="${d}" aria-pressed="${booking.date===d}" aria-label="${fmtDate(d)}, escolher data">${svgArt(2)}<span>${dateObj(d).toLocaleDateString('pt-BR',{weekday:'short',timeZone:ZONE})}</span><strong>${d.slice(8)}</strong><span>${available(s,booking.service,d).length} horários</span></button>`).join('')}</div>`:'<div class="empty"><h3>Uma pausa nesta quinzena.</h3><p>Não há horários livres. Veja o próximo período ou fale com o ateliê.</p></div>'}${booking.date?`<div style="margin-top:25px"><label>Horários de ${fmtDate(booking.date)}</label><div class="times" role="group" aria-label="Horários disponíveis">${available(s,booking.service,booking.date).map(t=>`<button class="time" data-time="${t}" aria-pressed="${booking.time===t}">${t}</button>`).join('')}</div></div>`:''}<p class="muted" style="margin-top:17px">São Paulo · Reservas com no mínimo 1 hora de antecedência · Próximos 180 dias.</p>`}
function summary(a){return `<dl class="summary-list"><div><dt>Leitura</dt><dd>${esc(a.title)}</dd></div><div><dt>Data e hora</dt><dd>${fmtDate(a.date)}<br>${a.time} · São Paulo</dd></div><div><dt>Formato</dt><dd>${a.mode==='online'?'Online':'Presencial'} · ${a.duration} minutos</dd></div><div><dt>Valor combinado</dt><dd>${money(a.price)}</dd></div><div><dt>Nome</dt><dd>${esc(a.name)}</dd></div><div><dt>E-mail</dt><dd>${esc(a.email)}</dd></div></dl>`}
function confirmation(a){return `<div class="success"><div class="confirm-seal" aria-hidden="true">✓</div><div class="eyebrow">Pedido registrado com segurança</div><h2 style="margin-top:14px">Seu tempo está reservado.</h2><p>A solicitação está <strong>pendente de confirmação</strong>. Acompanhe pelo seu caderno. Não enviamos e-mail ou WhatsApp automaticamente.</p>${summary(a)}<div class="flow-actions" style="justify-content:center;flex-wrap:wrap"><button class="btn" data-ics="${a.id}">Adicionar ao calendário ↓</button><a class="btn outline" href="${IS_ADMIN?'#admin':'#client'}">${IS_ADMIN?'Voltar à agenda':'Abrir meu caderno'} →</a></div></div>`}
function formError(text,el=$('#form-error')){if(el){el.className='form-error';el.textContent=text;el.setAttribute('tabindex','-1');el.focus()}else toast(text)}
function bindBook(){const s=read();$$('[data-service]').forEach(b=>b.onclick=()=>{booking.service=b.dataset.service;booking.date='';booking.time='';render();$('[data-service="'+booking.service+'"]')?.focus()});$('#prev')?.addEventListener('click',()=>{captureCustomer();booking.step--;render();focusBooking()});$('#next')?.addEventListener('click',()=>{if(booking.step===1&&(!available(read(),booking.service,booking.date).includes(booking.time)||!$('#booking-mode')?.value)){toast('Escolha uma modalidade e um horário disponível.');return}booking.step++;render();focusBooking()});$('#booking-mode')?.addEventListener('change',e=>booking.mode=e.target.value);['cards','list'].forEach(v=>$('#view-'+v)?.addEventListener('click',()=>{booking.view=v;render()}));$('#earlier')?.addEventListener('click',()=>{booking.offset=Math.max(0,booking.offset-14);booking.date='';booking.time='';render()});$('#later')?.addEventListener('click',()=>{booking.offset=Math.min(168,booking.offset+14);booking.date='';booking.time='';render()});$$('[data-date]').forEach(b=>b.onclick=()=>{booking.date=b.dataset.date;booking.time='';render();$('[data-date="'+booking.date+'"]')?.focus()});$$('[data-time]').forEach(b=>b.onclick=()=>{booking.time=b.dataset.time;render();$('[data-time="'+booking.time+'"]')?.focus()});$('#client-form')?.addEventListener('submit',e=>{e.preventDefault();captureCustomer();const c=booking.customer;let error='';if(c.name.trim().length<2)error='Me conte seu nome, com pelo menos duas letras.';else if(!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(c.email))error='Confira seu e-mail. Exemplo: nome@email.com.';else if(!/^[1-9]{2}9\d{8}$/.test(c.phone.replace(/\D/g,'')))error='Informe um celular brasileiro com DDD e nove dígitos. Exemplo: (11) 99999-9999.';else if(!c.topic)error='Escolha um tema — pode deixar a questão em aberto.';else if(!booking.consent)error='Aceite o uso dos dados e a política de remarcação para continuar.';if(error)return formError(error);booking.step=3;render();focusBooking()});$('#reserve')?.addEventListener('click',reserve);}
function focusBooking(){const h=$('#booking-panel h2');if(h){h.setAttribute('tabindex','-1');h.focus({preventScroll:true})}}
function captureCustomer(){const f=$('#client-form');if(!f)return;const fd=new FormData(f);for(const k of ['name','email','phone','topic','intention'])booking.customer[k]=String(fd.get(k)||'').trim();booking.customer.email=booking.customer.email.toLowerCase();booking.consent=fd.has('consent')}
async function reserve(){const btn=$('#reserve');btn.disabled=true;try{const id=await transact(s=>{if(!available(s,booking.service,booking.date).includes(booking.time))throw Error('Este horário acabou de ficar indisponível. Volte e escolha outro horário.');if(!(booking.mode==='online'?s.settings.online:s.settings.presential))throw Error('Esta modalidade não está mais disponível. Volte e escolha outra.');const sv=s.services.find(x=>x.id===booking.service);const a={id:uid(),service:sv.id,title:sv.title,duration:sv.duration,price:sv.price,date:booking.date,time:booking.time,mode:booking.mode,...booking.customer,status:'pendente',created:new Date().toISOString(),notes:'',cards:'',video:'',location:booking.mode==='presencial'?s.settings.address:''};s.appointments.push(a);return a.id});booking.done=id;clientEmail=booking.customer.email;render();toast('Reserva salva no servidor. Acompanhe pelo seu caderno.')}catch(e){formError(e.message);btn.disabled=false}}
function ics(a){const escapeICS=s=>String(s).replace(/\\/g,'\\\\').replace(/\r?\n/g,'\\n').replace(/,/g,'\\,').replace(/;/g,'\\;');const stamp=ms=>new Date(ms).toISOString().replace(/[-:]/g,'').split('.')[0]+'Z';const start=instant(a.date,a.time);const content=['BEGIN:VCALENDAR','VERSION:2.0','PRODID:-//estreladaconciencia//Atelie de Tarot//PT-BR','CALSCALE:GREGORIAN','METHOD:PUBLISH','BEGIN:VEVENT','UID:'+a.id+'@estreladaconciencia','DTSTAMP:'+stamp(Date.now()),'DTSTART:'+stamp(start),'DTEND:'+stamp(start+a.duration*60000),'SUMMARY:'+escapeICS(a.title+' — estreladaconciencia'),'DESCRIPTION:'+escapeICS('Status: '+statusLabel(a.status)+'. Horário de São Paulo. '+(a.video?'Link: '+a.video:'Acompanhe os detalhes no seu caderno.')),'LOCATION:'+escapeICS(a.mode==='online'?(a.video||'Online — link após confirmação'):a.location),'STATUS:'+(a.status==='cancelado'||a.status==='recusado'?'CANCELLED':a.status==='pendente'?'TENTATIVE':'CONFIRMED'),'END:VEVENT','END:VCALENDAR'];const enc=new TextEncoder();const folded=content.flatMap(line=>{let part='',bytes=0,lines=[];for(const char of line){const n=enc.encode(char).length;if(bytes+n>74){lines.push(part);part=' ';bytes=1}part+=char;bytes+=n}lines.push(part);return lines});download('consulta-'+a.date+'.ics',folded.join('\r\n')+'\r\n','text/calendar;charset=utf-8')}
function statusLabel(s){return {pendente:'Aguardando confirmação',confirmado:'Confirmada',recusado:'Recusada',cancelado:'Cancelada',concluido:'Concluída'}[s]||s}
function appointmentCard(a,admin=false){const past=instant(a.date,a.time)<Date.now();return `<article class="appointment"><div class="date-block"><strong>${a.date.slice(8)}</strong><span>${dateObj(a.date).toLocaleDateString('pt-BR',{month:'short',timeZone:ZONE})}</span><br><span>${a.time}</span></div><div><span class="badge ${a.status}">${statusLabel(a.status)}</span><h3>${esc(a.title)}</h3><p>${admin?esc(a.name)+' · ':''}${a.mode==='online'?'Online':'Presencial'} · ${a.duration} min · ${money(a.price)}</p><p class="muted">${fmtDate(a.date)} · São Paulo</p>${admin?`<p>${esc(a.email)} · ${esc(a.phone)}</p><p><strong>Intenção:</strong> ${esc(a.topic)}${a.intention?' — '+esc(a.intention):''}</p>`:''}${a.status==='confirmado'&&a.mode==='online'&&a.video?`<a class="text-link" href="${esc(a.video)}" target="_blank" rel="noopener noreferrer">Acessar videochamada ↗</a>`:''}${a.mode==='presencial'&&a.location?'<p>Local: '+esc(a.location)+'</p>':''}${a.status==='recusado'&&a.reason?'<p>Motivo: '+esc(a.reason)+'</p>':''}${!admin&&activeStatus(a.status)&&!canChange(a)?'<p class="muted">Prazo de alteração encerrado. Fale com o ateliê.</p>':''}</div><div class="appointment-actions">${admin?`${a.status==='pendente'?`<button class="btn small" data-confirm="${a.id}">Confirmar</button><button class="btn outline small" data-reject="${a.id}">Recusar</button>`:''}${['pendente','confirmado','concluido'].includes(a.status)?`<button class="btn outline small" data-notes="${a.id}">Caderno / detalhes</button>`:''}`:''}${activeStatus(a.status)?`<button class="btn outline small" data-reschedule="${a.id}" ${!admin&&!canChange(a)?'disabled':''}>Remarcar</button><button class="text-link" data-cancel="${a.id}" ${!admin&&!canChange(a)?'disabled':''}>Cancelar</button>`:''}${!admin&&['pendente','confirmado'].includes(a.status)?`<button class="text-link" data-ics="${a.id}">Calendário .ics ↓</button>`:''}</div></article>`}
function clientPage(){const s=read();if(!s.user)return pageTop('Meu caderno','Suas leituras, protegidas.','Entre para consultar os encontros da sua conta.')+'<section class="wrap workspace"><a class="btn" href="/signin-with-chatgpt?return_to=%2F%23client" target="_top">Entrar com ChatGPT →</a></section>';clientEmail=s.user.email.toLowerCase();const list=s.appointments.filter(a=>a.email===clientEmail).sort((a,b)=>instant(a.date,a.time)-instant(b.date,b.time));const upcoming=list.filter(a=>activeStatus(a.status)&&instant(a.date,a.time)>=Date.now());const history=list.filter(a=>!upcoming.includes(a));return pageTop('Meu caderno / registros do encontro','O que fica<br><em>depois das cartas.</em>','Seus próximos encontros, leituras anteriores e anotações compartilhadas em um só lugar.')+`<section class="wrap workspace"><div class="notice">Conectado como <strong>${esc(s.user.email)}</strong>. Este caderno é exclusivo da sua conta. <a href="/signout-with-chatgpt?return_to=%2F" target="_top">Sair</a></div>${clientEmail?`<h2 style="font-size:31px;margin-top:40px">Próximos encontros</h2>${upcoming.length?upcoming.map(a=>appointmentCard(a)).join(''):'<div class="empty"><h3>A próxima página está em branco.</h3><p>Você ainda não tem encontros futuros na sua conta.</p><a class="text-link" href="#book">Escolher uma leitura ↗</a></div>'}<h2 style="font-size:31px;margin-top:42px">Diário & histórico</h2>${history.length?'<div class="notebook">'+history.sort((a,b)=>instant(b.date,b.time)-instant(a.date,a.time)).map(a=>`<article class="journal-entry"><div class="eyebrow">${fmtDate(a.date)} · ${statusLabel(a.status)}</div><h3>${esc(a.title)}</h3>${a.cards?'<div class="journal-cards">Cartas à mesa: '+esc(a.cards)+'</div>':''}<div class="journal-body">${esc(a.notes||'Ainda não há anotações compartilhadas para este encontro.')}</div></article>`).join('')+'</div>':'<p class="muted">Após o encontro, as anotações da taróloga aparecerão aqui.</p>'}`:'<div class="empty"><h3>Seu caderno, sem pressa.</h3><p>Informe o e-mail da reserva para encontrar suas páginas.</p></div>'}</section>`}
function adminPage(){const s=read();return pageTop('Área da taróloga / bastidores do ateliê','Organize a mesa.<br><em>Cuide dos encontros.</em>','Agenda, serviços e anotações. Tudo que sustenta o atendimento, no seu ritmo.')+`<section class="wrap workspace"><div class="notice"><strong>Painel restrito à administradora.</strong> Agenda e configurações são salvas no banco do ateliê. ${!s.settings.configured?'Os valores e horários iniciais são sugestões. Revise seu nome, biografia, contato e serviços em Configurações.':'Use Exportar agenda para obter uma cópia dos registros.'}</div><div class="tabs" role="tablist" aria-label="Painel da taróloga">${[['agenda','Agenda'],['services','Serviços'],['availability','Disponibilidade'],['settings','Configurações']].map(([k,v])=>`<button role="tab" aria-controls="admin-content" aria-selected="${adminTab===k}" data-admin-tab="${k}">${v}</button>`).join('')}</div><div id="admin-content" role="tabpanel" aria-label="${esc(adminTab)}">${adminTab==='agenda'?adminAgenda(s):adminTab==='services'?adminServices(s):adminTab==='availability'?adminAvailability(s):adminSettings(s)}</div></section>`}
function adminAgenda(s){let list=s.appointments.filter(a=>adminFilter==='todos'||a.status===adminFilter).filter(a=>!searchTerm||(a.name+' '+a.email+' '+a.title+' '+a.date).toLowerCase().includes(searchTerm.toLowerCase())).sort((a,b)=>instant(a.date,a.time)-instant(b.date,b.time));const future=s.appointments.filter(a=>activeStatus(a.status)&&instant(a.date,a.time)>=Date.now());return `<div class="stats"><div class="stat"><strong>${s.appointments.filter(a=>a.status==='pendente').length}</strong><span>Aguardando resposta</span></div><div class="stat"><strong>${future.length}</strong><span>Próximos encontros</span></div><div class="stat"><strong>${s.appointments.filter(a=>a.status==='concluido').length}</strong><span>Leituras concluídas</span></div></div><div class="toolbar"><div class="field"><label for="agenda-search">Buscar nome, e-mail ou data</label><input id="agenda-search" type="search" value="${esc(searchTerm)}" placeholder="Nome ou AAAA-MM-DD"></div><div class="field"><label for="agenda-filter">Situação</label><select id="agenda-filter">${[['todos','Todas'],['pendente','Aguardando confirmação'],['confirmado','Confirmadas'],['concluido','Concluídas'],['cancelado','Canceladas'],['recusado','Recusadas']].map(([k,v])=>`<option value="${k}" ${adminFilter===k?'selected':''}>${v}</option>`).join('')}</select></div><button class="btn" id="new-admin-booking">Novo encontro +</button></div><div id="agenda-results">${list.length?list.map(a=>appointmentCard(a,true)).join(''):'<div class="empty"><h3>A mesa está pronta.</h3><p>Nenhum agendamento encontrado. Você pode registrar um novo encontro ou testar o fluxo de reserva.</p><a href="#book" class="text-link">Abrir agendamento ↗</a></div>'}</div>`}
function adminServices(s){return `<form id="services-form" class="panel"><h2>As formas da sua leitura.</h2><p class="muted">Alterações valem para novas reservas. Os encontros existentes mantêm o valor e a duração combinados.</p>${s.services.map(x=>`<fieldset class="service-edit" style="border-left:0;border-right:0;border-bottom:0"><legend class="eyebrow">${esc(x.id)}</legend><div class="field-grid"><div class="field"><label for="title-${x.id}">Nome da leitura</label><input id="title-${x.id}" name="title-${x.id}" value="${esc(x.title)}" required maxlength="60"></div><div class="field-grid"><div class="field"><label for="duration-${x.id}">Duração (min)</label><input id="duration-${x.id}" name="duration-${x.id}" type="number" min="15" max="240" step="15" value="${x.duration}" required></div><div class="field"><label for="price-${x.id}">Valor (R$)</label><input id="price-${x.id}" name="price-${x.id}" type="number" min="0" max="100000" step="0.01" value="${x.price}" required></div></div></div><div class="field"><label for="description-${x.id}">O que esperar</label><textarea id="description-${x.id}" name="description-${x.id}" required maxlength="600">${esc(x.description)}</textarea></div><label class="check"><input type="checkbox" name="active-${x.id}" ${x.active?'checked':''}>Disponível para novas reservas</label></fieldset>`).join('')}<div id="form-error" role="alert"></div><button class="btn" type="submit">Salvar serviços →</button></form>`}
function adminAvailability(s){const days=['Domingo','Segunda','Terça','Quarta','Quinta','Sexta','Sábado'];return `<div class="settings-grid"><form id="availability-form" class="panel"><h2>Seu ritmo semanal.</h2><p class="muted">Horários de São Paulo. Uma sessão precisa caber inteira no período.</p><div class="week-row"><span class="eyebrow">Dia</span><span class="eyebrow">Das</span><span class="eyebrow">Até</span></div>${s.settings.week.map((w,i)=>`<div class="week-row"><label class="check"><input type="checkbox" name="on${i}" ${w.on?'checked':''}>${days[i]}</label><input type="time" name="start${i}" value="${w.start}" aria-label="Início de ${days[i]}" required><input type="time" name="end${i}" value="${w.end}" aria-label="Fim de ${days[i]}" required></div>`).join('')}<div class="field" style="margin-top:25px"><label for="interval">Intervalo entre opções de início</label><select id="interval" name="interval">${[15,30,60].map(n=>`<option value="${n}" ${s.settings.interval===n?'selected':''}>${n} minutos</option>`).join('')}</select></div><div class="field"><label for="lead">Antecedência para cancelar / remarcar (horas)</label><input id="lead" name="lead" type="number" min="0" max="168" step="1" value="${s.settings.lead}" required></div><div id="form-error" role="alert"></div><button class="btn" type="submit">Salvar disponibilidade →</button></form><div class="panel"><h2>Dias de pausa.</h2><p class="muted">Bloqueie datas inteiras para férias, feriados ou descanso. Reservas existentes são preservadas.</p><form id="block-form"><div class="field"><label for="block-date">Data para bloquear</label><input type="date" id="block-date" required min="${today()}"></div><button class="btn outline" type="submit">Bloquear este dia +</button><div id="block-error" role="alert"></div></form><div style="margin-top:26px">${s.settings.blocked.sort().map(d=>`<div class="toolbar rule" style="padding-top:10px;justify-content:space-between"><span style="font-size:12px">${fmtDate(d)}</span><button class="text-link" data-unblock="${d}" aria-label="Liberar ${fmtDate(d)}">Liberar ×</button></div>`).join('')||'<p class="muted">Nenhuma data bloqueada.</p>'}</div></div></div>`}
function adminSettings(s){return `<div class="settings-grid"><form class="panel" id="settings-form"><h2>A voz do ateliê.</h2><div class="field"><label for="provider-name">Seu nome / assinatura</label><input id="provider-name" name="name" value="${esc(s.settings.name)}" maxlength="100"></div><div class="field"><label for="bio">Apresentação em primeira pessoa</label><textarea id="bio" name="bio" maxlength="2500" required style="min-height:210px">${esc(s.settings.bio)}</textarea><small>Texto editorial proposto. Personalize com sua história real.</small></div><div class="field"><label for="whatsapp">WhatsApp com DDD (opcional)</label><input id="whatsapp" name="whatsapp" type="tel" inputmode="tel" maxlength="16" value="${esc(s.settings.whatsapp)}" placeholder="(11) 99999-9999"><small>Sem número, o contato direciona ao Instagram. Não enviamos mensagens automaticamente.</small></div><label class="check"><input name="online" type="checkbox" ${s.settings.online?'checked':''}>Oferecer consultas online</label><div class="field" style="margin-top:15px"><label for="video">Link de vídeo padrão (opcional)</label><input id="video" name="video" type="url" value="${esc(s.settings.video)}" placeholder="https://"><small>Você também pode definir um link exclusivo ao confirmar cada consulta.</small></div><label class="check"><input name="presential" type="checkbox" ${s.settings.presential?'checked':''}>Oferecer consultas presenciais</label><div class="field" style="margin-top:15px"><label for="address">Endereço de atendimento</label><textarea id="address" name="address" maxlength="400">${esc(s.settings.address)}</textarea></div><div id="form-error" role="alert"></div><button class="btn" type="submit">Salvar identidade e contato →</button></form><div><div class="panel"><div class="eyebrow">Banco do ateliê</div><h2 style="margin-top:15px">Uma agenda, em todos os aparelhos.</h2><p class="muted">Agendamentos e configurações são persistidos no servidor. O acesso a este painel é restrito à conta autorizada.</p><button class="btn outline" id="export">Exportar agenda ↓</button><p class="muted" style="margin-top:22px">A exportação contém dados pessoais. Guarde o arquivo em um lugar privado.</p></div><div class="notice" style="margin-top:25px"><strong>Configuração do atendimento</strong><p>Antes de divulgar, confira seus valores, WhatsApp e link de vídeo. Confirmações ficam no caderno; mensagens e cobranças não são automáticas.</p></div></div></div>`}
function safeVideo(v){if(!v)return true;try{const u=new URL(v);return u.protocol==='https:'&&!u.username&&!u.password}catch{return false}}
function bindAdmin(){const s=read();$$('[data-admin-tab]').forEach((b,i,all)=>{b.onclick=()=>{adminTab=b.dataset.adminTab;render();$('[data-admin-tab="'+adminTab+'"]')?.focus()};b.onkeydown=e=>{if(['ArrowLeft','ArrowRight'].includes(e.key)){e.preventDefault();all[(i+(e.key==='ArrowRight'?1:all.length-1))%all.length].click()}}});$('#agenda-filter')?.addEventListener('change',e=>{adminFilter=e.target.value;render()});$('#agenda-search')?.addEventListener('input',e=>{searchTerm=e.target.value;const p=e.target.selectionStart;$('#agenda-results').innerHTML=adminAgenda(read()).split('<div id="agenda-results">')[1].slice(0,-6);bindAppointments(true);$('#agenda-search').setSelectionRange(p,p)});$('#new-admin-booking')?.addEventListener('click',()=>{booking={...booking,step:0,done:null,date:'',time:'',customer:{name:'',email:'',phone:'',topic:'',intention:''},consent:false};location.hash='book'});
 $('#services-form')?.addEventListener('submit',async e=>{e.preventDefault();const f=new FormData(e.target);await saveForm(async()=>transact(d=>{d.services=d.services.map(x=>({...x,title:String(f.get('title-'+x.id)).trim(),description:String(f.get('description-'+x.id)).trim(),duration:Number(f.get('duration-'+x.id)),price:Number(f.get('price-'+x.id)),active:f.has('active-'+x.id)}));if(d.services.some(x=>!x.title||!x.description||x.price>100000||x.duration%15))throw Error('Confira nomes, descrições, valores e duração em múltiplos de 15 minutos.')}),'Serviços atualizados. Reservas anteriores foram preservadas.')});
 $('#availability-form')?.addEventListener('submit',async e=>{e.preventDefault();const f=new FormData(e.target);await saveForm(()=>transact(d=>{const week=Array.from({length:7},(_,i)=>({on:f.has('on'+i),start:f.get('start'+i),end:f.get('end'+i)}));if(week.some(w=>!validTime(w.start)||!validTime(w.end)||minutes(w.start)>=minutes(w.end)))throw Error('Em cada dia, o fim precisa ser depois do início.');d.settings.week=week;d.settings.lead=Number(f.get('lead'));d.settings.interval=Number(f.get('interval'))}),'Disponibilidade atualizada. Reservas existentes foram preservadas.')});
 $('#block-form')?.addEventListener('submit',async e=>{e.preventDefault();try{const date=$('#block-date').value;await transact(d=>{if(!validDate(date)||date<today())throw Error('Escolha uma data válida a partir de hoje.');if(d.settings.blocked.includes(date))throw Error('Este dia já está bloqueado.');d.settings.blocked.push(date)});render();toast('Dia bloqueado. Agendamentos já existentes foram preservados.')}catch(err){formError(err.message,$('#block-error'))}});$$('[data-unblock]').forEach(b=>b.onclick=async()=>{try{await transact(d=>{d.settings.blocked=d.settings.blocked.filter(x=>x!==b.dataset.unblock)});render();toast('Dia liberado.')}catch(e){toast(e.message)}});
 $('#settings-form')?.addEventListener('submit',async e=>{e.preventDefault();const f=new FormData(e.target);await saveForm(()=>transact(d=>{const w=String(f.get('whatsapp')).replace(/\D/g,'');if(w&&!/^[1-9]{2}9\d{8}$/.test(w))throw Error('Confira o WhatsApp: DDD e nove dígitos, sem o código 55.');const video=String(f.get('video')).trim();if(!safeVideo(video))throw Error('Use um link de vídeo completo, começando com https://.');if(f.has('presential')&&!String(f.get('address')).trim())throw Error('Informe o endereço para habilitar o atendimento presencial.');if(!String(f.get('bio')).trim())throw Error('Escreva uma apresentação para o ateliê.');Object.assign(d.settings,{name:String(f.get('name')).trim(),bio:String(f.get('bio')).trim(),whatsapp:w,address:String(f.get('address')).trim(),video,online:f.has('online'),presential:f.has('presential'),configured:true})}),'Identidade e contato atualizados.')});
 $('#export')?.addEventListener('click',()=>download('estreladaconciencia-agenda-'+today()+'.json',JSON.stringify(read(),null,2),'application/json'));
}
async function saveForm(fn,msg){const btn=$('form button[type=submit]');if(btn)btn.disabled=true;try{await fn();render();toast(msg)}catch(e){formError(e.message);if(btn)btn.disabled=false}}
function bindAppointments(admin=false){$$('[data-ics]').forEach(b=>b.onclick=()=>{const a=read().appointments.find(a=>a.id===b.dataset.ics);if(a)ics(a)});$$('[data-cancel]').forEach(b=>b.onclick=()=>changeStatus(b.dataset.cancel,'cancelado',admin));$$('[data-reject]').forEach(b=>b.onclick=()=>changeStatus(b.dataset.reject,'recusado',true));$$('[data-confirm]').forEach(b=>b.onclick=()=>editAppointment(b.dataset.confirm,true));$$('[data-notes]').forEach(b=>b.onclick=()=>editAppointment(b.dataset.notes,false));$$('[data-reschedule]').forEach(b=>b.onclick=()=>reschedule(b.dataset.reschedule,admin))}
function changeStatus(id,status,admin){const a=read().appointments.find(x=>x.id===id);if(!a)return;if(!admin&&!canChange(a)){toast('O prazo de alteração encerrou. Fale com o ateliê.');return}const d=modal(status==='recusado'?'Recusar solicitação?':'Cancelar este encontro?',`<p>${esc(a.title)} · ${fmtDate(a.date)} às ${a.time}.</p><p>O horário será liberado. O registro ficará no histórico.</p>${status==='recusado'?'<label for="reason">Motivo para o cliente *</label><textarea id="reason" maxlength="500" required></textarea>':''}<div id="dialog-error" role="alert"></div><button class="btn" id="status-confirm" style="margin-top:20px">${status==='recusado'?'Recusar solicitação':'Confirmar cancelamento'}</button>`);$('#status-confirm',d).onclick=async()=>{const reason=$('#reason')?.value.trim()||'';try{if(status==='recusado'&&!reason)throw Error('Informe um motivo breve para o cliente.');await transact(s=>{const current=s.appointments.find(x=>x.id===id);if(!current||!activeStatus(current.status))throw Error('Este encontro já foi atualizado em outra aba.');if(!admin&&!canChange(current,s))throw Error('O prazo de alteração encerrou. Fale com o ateliê.');if(status==='recusado'&&current.status!=='pendente')throw Error('A solicitação já não está pendente.');current.status=status;current.reason=reason});d.close();render();toast(status==='recusado'?'Solicitação recusada.':'Encontro cancelado.')}catch(e){formError(e.message,$('#dialog-error'))}}}
function editAppointment(id,confirming){const s=read(),a=s.appointments.find(x=>x.id===id);if(!a)return;const canComplete=instant(a.date,a.time)+a.duration*60000<=Date.now();const d=modal(confirming?'Confirmar o encontro':'Caderno do encontro',`<p>${esc(a.name)} · ${esc(a.title)}<br>${fmtDate(a.date)} às ${a.time}</p><form id="notes-form">${a.mode==='online'?`<div class="field"><label for="appointment-video">Link de videochamada ${confirming?'*':''}</label><input id="appointment-video" name="video" type="url" value="${esc(a.video||s.settings.video)}" ${confirming?'required':''} placeholder="https://"></div>`:`<div class="field"><label for="appointment-location">Endereço do encontro *</label><textarea id="appointment-location" name="location" required maxlength="400">${esc(a.location||s.settings.address)}</textarea></div>`}${!confirming?`<div class="field"><label for="cards">Cartas que saíram</label><input id="cards" name="cards" value="${esc(a.cards)}" maxlength="300" placeholder="Ex.: A Lua, A Imperatriz, O Sol"></div><div class="field"><label for="notes">Anotações compartilhadas com o cliente</label><textarea id="notes" name="notes" maxlength="5000" style="min-height:170px">${esc(a.notes)}</textarea></div><label class="check"><input name="complete" type="checkbox" ${a.status==='concluido'?'checked':''} ${!canComplete?'disabled':''}>Marcar consulta como concluída</label>${!canComplete?'<p class="muted">A conclusão fica disponível após o horário final da sessão.</p>':''}`:'<p class="muted">A confirmação aparece no caderno do cliente. Nenhuma mensagem é enviada automaticamente.</p>'}<div id="dialog-error" role="alert"></div><button class="btn" type="submit" style="margin-top:20px">${confirming?'Confirmar encontro →':'Salvar caderno →'}</button></form>`);$('#notes-form',d).onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target);try{await transact(st=>{const cur=st.appointments.find(x=>x.id===id);if(!cur||!['pendente','confirmado','concluido'].includes(cur.status))throw Error('Este encontro mudou de situação em outra aba.');if(confirming&&cur.status!=='pendente')throw Error('A solicitação já foi respondida.');const video=String(f.get('video')||'').trim();if(cur.mode==='online'&&(!safeVideo(video)||(confirming&&!video)))throw Error('Informe o link https:// da videochamada.');const location=String(f.get('location')||'').trim();if(cur.mode==='presencial'&&!location)throw Error('Informe o endereço do encontro.');cur.video=video;cur.location=location;if(confirming)cur.status='confirmado';else{cur.notes=String(f.get('notes')).trim();cur.cards=String(f.get('cards')).trim();if(f.has('complete')){if(instant(cur.date,cur.time)+cur.duration*60000>Date.now())throw Error('Aguarde o encerramento do horário para concluir.');cur.status='concluido'}}});d.close();render();toast(confirming?'Encontro confirmado.':'Caderno salvo.')}catch(err){formError(err.message,$('#dialog-error'))}}}
function reschedule(id,admin){const s=read(),a=s.appointments.find(x=>x.id===id);if(!a)return;if(!admin&&!canChange(a)){toast('Prazo encerrado. Fale com o ateliê.');return}if(!s.services.some(x=>x.id===a.service&&x.active)){toast('Este serviço está indisponível para novas datas. Ative-o no painel para remarcar.');return}const d=modal('Uma nova data para a conversa.',`<p>${esc(a.title)} · ${a.duration} min. ${admin?'Você está alterando pelo painel da taróloga.':'A nova data volta a aguardar confirmação.'}</p><form id="reschedule-form"><div class="field"><label for="new-date">Novo dia</label><input type="date" id="new-date" min="${today()}" max="${addDays(today(),180)}" required></div><div class="field"><label for="new-time">Horário</label><select id="new-time" required><option value="">Escolha o dia primeiro</option></select></div><div id="dialog-error" role="alert"></div><button class="btn" type="submit">Salvar nova data →</button></form>`);function slots(){const st=structuredClone(read());st.services.find(x=>x.id===a.service).duration=a.duration;return available(st,a.service,$('#new-date').value,a.id)}$('#new-date').onchange=()=>{const times=slots();$('#new-time').innerHTML=times.length?times.map(t=>`<option>${t}</option>`).join(''):'<option value="">Sem horários disponíveis neste dia</option>'};$('#reschedule-form').onsubmit=async e=>{e.preventDefault();const date=$('#new-date').value,time=$('#new-time').value;try{await transact(st=>{const cur=st.appointments.find(x=>x.id===id);if(!cur||!activeStatus(cur.status))throw Error('Este encontro não pode mais ser remarcado.');if(!admin&&!canChange(cur,st))throw Error('O prazo de alteração encerrou.');const check=structuredClone(st);check.services.find(x=>x.id===cur.service).duration=cur.duration;if(!available(check,cur.service,date,id).includes(time))throw Error('O horário não está mais disponível. Escolha outro.');cur.date=date;cur.time=time;cur.status='pendente';cur.video=''});d.close();render();toast('Nova data reservada, aguardando confirmação.')}catch(err){formError(err.message,$('#dialog-error'))}}}
let previousRoute='';
function render(){const hash=(location.hash||(IS_ADMIN?'#admin':'#home')).slice(1);const route=hash.split('/')[0];const main=$('#main');const scroll=window.scrollY;const same=previousRoute===route;read();if(route==='admin'&&!IS_ADMIN){location.href=ADMIN_URL;return}if(route==='book'){if(!['online','presencial'].includes(booking.mode)||(booking.mode==='online'&&!read().settings.online)||(booking.mode==='presencial'&&!read().settings.presential))booking.mode=read().settings.online?'online':'presencial';main.innerHTML=bookPage();bindBook()}else if(route==='client'){main.innerHTML=clientPage();}else if(route==='admin'){main.innerHTML=adminPage();bindAdmin()}else main.innerHTML=home();bindAppointments(route==='admin');$$('[data-contact]').forEach(b=>b.onclick=contact);$$('[data-privacy]').forEach(b=>b.onclick=privacy);$('#year').textContent=new Date().getFullYear();if(!same){main.classList.remove('fade-in');void main.offsetWidth;main.classList.add('fade-in')}previousRoute=route;if(['services','about','how','faq'].includes(route))requestAnimationFrame(()=>$('#'+route)?.scrollIntoView({behavior:'auto'}));else if(same)window.scrollTo(0,scroll);else window.scrollTo(0,0)}
window.addEventListener('hashchange',()=>{const hash=location.hash.slice(1);if(hash.startsWith('book')){const id=hash.split('/')[1];if(id&&read().services.some(s=>s.id===id&&s.active))booking={...booking,service:id,step:0,date:'',time:'',done:null};else if(booking.done)booking={...booking,step:0,date:'',time:'',done:null}}$('#navigation').classList.remove('open');$('#menu').setAttribute('aria-expanded','false');render();if(!['#services','#about','#how','#faq'].includes(location.hash))$('#main').focus({preventScroll:true})});

$('#menu').onclick=()=>{const open=$('#navigation').classList.toggle('open');$('#menu').setAttribute('aria-expanded',String(open))};document.addEventListener('keydown',e=>{if(e.key==='Escape'){$('#navigation').classList.remove('open');$('#menu').setAttribute('aria-expanded','false')}});$('#dialog').addEventListener('click',e=>{if(e.target===$('#dialog')){const rect=e.target.getBoundingClientRect();if(e.clientX<rect.left||e.clientX>rect.right||e.clientY<rect.top||e.clientY>rect.bottom)e.target.close()}});
if(location.hash.startsWith('#book/')){const id=location.hash.split('/')[1];if(read().services.some(s=>s.id===id))booking.service=id}async function initialize(){try{await fetchState();if(memory.user&&!IS_ADMIN){booking.customer.name=memory.user.name||'';booking.customer.email=memory.user.email;clientEmail=memory.user.email.toLowerCase()}render()}catch(e){$('#main').innerHTML='<section class="wrap section"><h1>Uma pausa na conexão.</h1><p>'+esc(e.message)+'</p><button class="btn" id="retry-load">Tentar novamente</button></section>';$('#retry-load').onclick=initialize}}
initialize();
window.addEventListener('focus',()=>fetchState().catch(()=>{}));
